(()=>{const e=window.matchMedia("(min-width: 80rem)");document.querySelectorAll(".post-toc").forEach(t=>{const n=t.querySelector(":scope > summary");if(!n)return;const s=()=>{e.matches&&(t.open=!0),n.tabIndex=e.matches?-1:0,n.setAttribute("aria-disabled",String(e.matches))};n.addEventListener("keydown",n=>{if(!e.matches||n.key!=="Enter"&&n.key!==" ")return;n.preventDefault(),t.open=!0}),e.addEventListener("change",s),s()})})()